SELECT r.receipt_id, r.receipt_no, r.doc_id, r.doc_type, DATE_FORMAT(r.order_date, '%Y-%m-%d %H:%i') AS order_date, r.partner_name, r.requester_id, r.approver_id, r.total_amount, r.status, COALESCE( r.confirmed_no, CASE WHEN r.status = 'CONFIRMED' AND r.receipt_no LIKE 'OCR-%' THEN CONCAT('OCR-CONF-', DATE_FORMAT(r.created_at, '%Y%m%d%H%i%s'), '-', r.receipt_id) ELSE NULL END ) AS confirmed_no, DATE_FORMAT(r.created_at, '%Y-%m-%d %H:%i') AS created_at, req.name AS requester_name, apr.name AS approver_name, d.doc_no FROM order_receipt r LEFT JOIN member req ON r.requester_id = req.member_id LEFT JOIN member apr ON r.approver_id = apr.member_id LEFT JOIN approval_doc d ON r.doc_id = d.doc_id
r.doc_type = #{searchDocType}
AND (r.receipt_no LIKE CONCAT('%', #{searchKeyword}, '%') OR r.partner_name LIKE CONCAT('%', #{searchKeyword}, '%'))
AND r.status = #{searchStatus}
ORDER BY r.created_at DESC

SELECT COUNT(*) FROM order_receipt r


        r.doc_type = #{searchDocType}


        AND (r.receipt_no   LIKE CONCAT('%', #{searchKeyword}, '%')
          OR r.partner_name LIKE CONCAT('%', #{searchKeyword}, '%'))


        AND r.status = #{searchStatus}

SELECT COUNT(*)
FROM   order_receipt
WHERE  partner_name = #{partnerName}
  AND  total_amount = #{totalAmount}
  AND  status       = 'CONFIRMED'
  AND  DATE(created_at) = CURDATE()
  AND  receipt_id  != #{excludeId}

